// 11 §K6 migration (@m4, §18.5): the committed pilot DB (K7 `v1-populated.sqlite`, generated by make-fixture-db.ts)
// opens with the current build: pending migrations apply, a pre-migration backup is created, and every run's balances
// are identical before and after. The committed file is never opened in place (copied to a temp userData first).
import { existsSync } from 'node:fs';
import { copyFile, readdir } from 'node:fs/promises';
import { join } from 'node:path';
import { afterEach, describe, expect, it } from 'vitest';
import { systemClock } from '@relay/contracts';
import type { RunId } from '@relay/contracts';
import { MIGRATIONS, openTestDb } from '@relay/storage';
import type { Migration } from '@relay/storage';
import { createHarness } from '../helpers/engine-harness.js';
import type { Harness } from '../helpers/engine-harness.js';
import { FIXTURE_DB_PATH } from '../helpers/make-fixture-db.js';
import { integrityCheck, queryAll } from '../helpers/sqlite-inspect.js';
import { cleanupTempDirs, copyFixture, makeTempDir } from '../helpers/temp-dirs.js';

let h: Harness | undefined;
afterEach(async () => {
  await h?.dispose();
  h = undefined;
  await cleanupTempDirs();
});

type Bal = Record<string, { C: number; R: number; U: number; L: number }>;

/** Balances per run straight from ledger_entries (independent of the repos under test). */
function sqlBalances(dbPath: string): Bal {
  const rows = queryAll(dbPath, "SELECT run_id AS runId, bucket, SUM(delta_microusd) AS total FROM ledger_entries WHERE scope = 'run' GROUP BY run_id, bucket");
  const out: Bal = {};
  for (const r of rows) {
    const id = String(r['runId']);
    const b = (out[id] ??= { C: 0, R: 0, U: 0, L: 0 });
    const t = Number(r['total']);
    if (r['bucket'] === 'settled') b.C = t;
    else if (r['bucket'] === 'reserved') b.R = t;
    else if (r['bucket'] === 'unknown') b.U = t;
    else if (r['bucket'] === 'allowance') b.L = t;
  }
  return out;
}

async function freshCopy(): Promise<{ userDataDir: string; dbPath: string }> {
  const userDataDir = await makeTempDir('relay-migration-ud-');
  const dbPath = join(userDataDir, 'relay.sqlite');
  await copyFile(FIXTURE_DB_PATH, dbPath);
  return { userDataDir, dbPath };
}

describe.skipIf(!existsSync(FIXTURE_DB_PATH))('migration @m4', () => {
  it('the pilot DB opens with the current build: integrity ok, migrations applied (pre-migration backup when any were pending), balances identical @m4', async () => {
    const { userDataDir, dbPath } = await freshCopy();
    expect(integrityCheck(dbPath)).toBe('ok');
    const fromVersion = Number(queryAll(dbPath, 'SELECT MAX(version) AS v FROM schema_migrations')[0]?.['v']);
    const before = sqlBalances(dbPath);
    expect(Object.keys(before).length).toBeGreaterThanOrEqual(3);
    expect(Number(queryAll(dbPath, 'SELECT COUNT(*) AS c FROM memory_records')[0]?.['c'])).toBeGreaterThan(0);

    h = await createHarness({ userDataDir, projectRoot: await copyFixture('sample-api'), start: false });

    expect(h.db.schemaVersion()).toBe(MIGRATIONS.length);
    // The committed fixture is a schema-v1 DB, so this is a real upgrade (0002 indexes) — not a no-op open.
    expect(fromVersion).toBeLessThan(MIGRATIONS.length);
    const indexes = queryAll(dbPath, "SELECT name FROM sqlite_master WHERE type = 'index'").map((r) => r['name']);
    expect(indexes).toEqual(expect.arrayContaining(['attempts_run_idx', 'memory_events_record_idx', 'run_memory_snapshot_record_idx',
      'run_events_type_idx', 'ledger_project_window_idx']));
    expect(integrityCheck(dbPath)).toBe('ok');
    const backups = existsSync(join(userDataDir, 'backups')) ? await readdir(join(userDataDir, 'backups')) : [];
    if (fromVersion < MIGRATIONS.length) expect(backups.some((b) => b.includes(`-pre-v${String(MIGRATIONS.length)}`))).toBe(true);
    else expect(backups).toEqual([]); // nothing pending → no pre-migration backup
    for (const [runId, b] of Object.entries(before)) expect(h.db.repos.ledger.runBalances(runId as RunId), runId).toEqual(b);
    const statuses = queryAll(dbPath, 'SELECT status FROM runs ORDER BY created_at').map((r) => r['status']);
    expect(statuses).toEqual(expect.arrayContaining(['completed', 'paused']));
  });

  it('a forward migration over the pilot DB takes a pre-migration backup and keeps every balance (synthetic next version) @m4', async () => {
    const { userDataDir, dbPath } = await freshCopy();
    const before = sqlBalances(dbPath);
    const fromVersion = Number(queryAll(dbPath, 'SELECT MAX(version) AS v FROM schema_migrations')[0]?.['v']);
    const next: Migration = { version: MIGRATIONS.length + 1, name: 'k7_probe', sql: 'CREATE TABLE k7_probe (id INTEGER PRIMARY KEY);' };

    const db = await openTestDb({ path: dbPath, clock: systemClock, backupsDir: join(userDataDir, 'backups'), migrations: [...MIGRATIONS, next] });
    try {
      expect(db.schemaVersion()).toBe(next.version);
      for (const [runId, b] of Object.entries(before)) expect(db.repos.ledger.runBalances(runId as RunId), runId).toEqual(b);
    } finally {
      await db.dispose();
    }

    const backups = await readdir(join(userDataDir, 'backups'));
    const pre = backups.find((b) => b.endsWith(`-pre-v${String(next.version)}`));
    expect(pre).toBeDefined();
    const backupDb = join(userDataDir, 'backups', pre!, 'relay.sqlite');
    expect(integrityCheck(backupDb)).toBe('ok');
    expect(sqlBalances(backupDb)).toEqual(before);
    // The backup is the DB as it was before ANY pending migration ran (the fixture's own version).
    expect(Number(queryAll(backupDb, 'SELECT MAX(version) AS v FROM schema_migrations')[0]?.['v'])).toBe(fromVersion);
  });
});
